using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Invoices.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Invoices.Queries.GetInvoiceById;public sealed class GetInvoiceByIdQueryHandler(IInvoiceRepository repository):IRequestHandler<GetInvoiceByIdQuery,Result<InvoiceDto>>{public async Task<Result<InvoiceDto>>Handle(GetInvoiceByIdQuery request,CancellationToken cancellationToken){var e=await repository.FindByIdAsync(request.Id,cancellationToken);return e is null?Result.Failure<InvoiceDto>(InvoiceErrors.NotFound):Result.Success(InvoiceDto.FromEntity(e));}}
